#!/usr/bin/env python3
from pathlib import Path
import argparse, shutil, tempfile

REL = {
    'safe':'app/src/main/java/com/hinnka/mycamera/model/SafeImage.kt',
    'frame':'app/src/main/java/com/particlesdevs/photoncamera/processing/ImageFrame.java',
    'capture':'app/src/main/java/com/particlesdevs/photoncamera/capture/CaptureController.java',
    'bridge':'app/src/main/java/com/particlesdevs/photoncamera/processing/processor/PhotonMotionMgc1271Bridge.kt',
    'stacker':'app/src/main/java/com/hinnka/mycamera/processor/GlesIris26521SpatialRgbStacker.kt',
    'shaders':'app/src/main/java/com/hinnka/mycamera/processor/GlesIris26521SpatialRgbShaders.kt',
    'night':'app/src/main/java/com/particlesdevs/photoncamera/processing/processor/IrisNightProcessor.java',
    'version':'app/version.properties',
}

def once(s, old, new, label):
    n=s.count(old)
    if n != 1:
        raise RuntimeError(f'{label}: expected 1 anchor, found {n}')
    return s.replace(old,new,1)

def exact_count(s, token, n, label):
    c=s.count(token)
    if c != n:
        raise RuntimeError(f'{label}: expected {n}, found {c}')

def transform(root: Path):
    v=(root/REL['version']).read_text()
    if 'VERSION_NAME=0.9726542' not in v or 'VERSION_BUILD=26542' not in v:
        raise RuntimeError('not exact 26542 base version')

    # SafeImage: add disk-backed row-region reads so the active stacker can upload one frame/tile
    # without materializing every spooled RAW into anonymous native memory.
    p=root/REL['safe']
    p.write_text('''package com.hinnka.mycamera.model\n\nimport com.hinnka.mycamera.utils.LargeDirectBuffer\nimport com.hinnka.mycamera.utils.PLog\nimport java.io.File\nimport java.io.FileInputStream\nimport java.nio.ByteBuffer\nimport java.nio.ByteOrder\nimport java.util.concurrent.atomic.AtomicBoolean\n\n/**\n * IRIS_26512_MGC1271_IMMUTABLE_SAFE_IMAGE_ADAPTER\n * Minimal plane contract consumed by pinned bjzhou 1.27.1 MGC Spatial.\n *\n * IRIS_26543_NIGHT_BOUNDED_DISK_BACKING\n * Night may back non-reference RAWs with immutable cache files. The live Spatial owner reads only\n * the full frame or tile region needed for the current GPU upload into one temporary Photon native\n * buffer, then frees it immediately. Frame count therefore does not multiply anonymous RAW RAM.\n */\nclass SafeImage private constructor(\n    val width: Int,\n    val height: Int,\n    val format: Int,\n    val timestamp: Long,\n    buffer: ByteBuffer?,\n    val rowStrideBytes: Int,\n    val pixelStrideBytes: Int,\n    private val backingFile: File?,\n    private val backingByteCount: Int,\n    private val closeAction: (() -> Unit)? = null,\n) : AutoCloseable {\n    class Plane(\n        val buffer: ByteBuffer,\n        val rowStride: Int,\n        val pixelStride: Int,\n    )\n\n    class FileRegion internal constructor(\n        val buffer: ByteBuffer,\n        val rowStride: Int,\n        val pixelStride: Int,\n    ) : AutoCloseable {\n        private val closed = AtomicBoolean(false)\n        override fun close() {\n            if (closed.compareAndSet(false, true)) LargeDirectBuffer.free(buffer)\n        }\n    }\n\n    private val closed = AtomicBoolean(false)\n    private val memoryPlane: Array<Plane> = if (buffer != null) {\n        arrayOf(Plane(buffer.duplicate().apply { position(0) }, rowStrideBytes, pixelStrideBytes))\n    } else {\n        emptyArray()\n    }\n\n    val planes: Array<Plane> get() = memoryPlane\n    val isFileBacked: Boolean get() = backingFile != null\n\n    constructor(\n        width: Int, height: Int, format: Int, timestamp: Long, buffer: ByteBuffer,\n        rowStride: Int, pixelStride: Int, closeAction: (() -> Unit)? = null,\n    ) : this(\n        width, height, format, timestamp, buffer, rowStride, pixelStride,\n        null, 0, closeAction,\n    )\n\n    constructor(\n        width: Int, height: Int, format: Int, timestamp: Long, backingFile: File,\n        backingByteCount: Int, rowStride: Int, pixelStride: Int,\n        closeAction: (() -> Unit)? = null,\n    ) : this(\n        width, height, format, timestamp, null, rowStride, pixelStride,\n        backingFile, backingByteCount, closeAction,\n    ) {\n        require(backingByteCount > 0) { "Disk-backed RAW byte count must be positive" }\n        require(backingFile.isFile && backingFile.length() >= backingByteCount.toLong()) {\n            "Disk-backed RAW is unavailable: ${backingFile.absolutePath}"\n        }\n    }\n\n    /** Read a packed RAW16 rectangle without retaining the entire disk-backed frame in RAM. */\n    fun readFileRegion(left: Int, top: Int, regionWidth: Int, regionHeight: Int): FileRegion {\n        check(!closed.get()) { "SafeImage is closed" }\n        val file = checkNotNull(backingFile) { "SafeImage is not disk-backed" }\n        require(pixelStrideBytes == 2) { "Disk-backed RAW pixel stride=$pixelStrideBytes, expected 2" }\n        require(left >= 0 && top >= 0 && regionWidth > 0 && regionHeight > 0)\n        require(left + regionWidth <= width && top + regionHeight <= height)\n        require(rowStrideBytes >= width * pixelStrideBytes)\n        val packedRowStride = regionWidth * pixelStrideBytes\n        val byteCountLong = packedRowStride.toLong() * regionHeight\n        require(byteCountLong in 1..Int.MAX_VALUE.toLong())\n        val byteCount = byteCountLong.toInt()\n        val output = LargeDirectBuffer.allocate(byteCountLong, "IRIS26543 Night RAW region")\n            ?: throw IllegalStateException("Unable to allocate $byteCount byte Night RAW upload region")\n        output.order(ByteOrder.nativeOrder())\n        try {\n            FileInputStream(file).channel.use { channel ->\n                if (left == 0 && packedRowStride == rowStrideBytes) {\n                    val sourceOffset = top.toLong() * rowStrideBytes\n                    val sourceEnd = sourceOffset + byteCountLong\n                    require(sourceOffset >= 0 && sourceEnd <= backingByteCount.toLong()) {\n                        "Disk RAW region exceeds backing bytes=$backingByteCount"\n                    }\n                    output.position(0)\n                    output.limit(byteCount)\n                    var position = sourceOffset\n                    while (output.hasRemaining()) {\n                        val read = channel.read(output, position)\n                        if (read < 0) throw IllegalStateException("Unexpected EOF in Night RAW spool")\n                        if (read == 0) continue\n                        position += read\n                    }\n                } else {\n                    for (row in 0 until regionHeight) {\n                        val sourceOffset =\n                            (top + row).toLong() * rowStrideBytes + left.toLong() * pixelStrideBytes\n                        val sourceEnd = sourceOffset + packedRowStride\n                        require(sourceOffset >= 0 && sourceEnd <= backingByteCount.toLong()) {\n                            "Disk RAW region exceeds backing bytes=$backingByteCount"\n                        }\n                        output.position(row * packedRowStride)\n                        output.limit((row + 1) * packedRowStride)\n                        var position = sourceOffset\n                        while (output.hasRemaining()) {\n                            val read = channel.read(output, position)\n                            if (read < 0) throw IllegalStateException("Unexpected EOF in Night RAW spool")\n                            if (read == 0) continue\n                            position += read\n                        }\n                    }\n                }\n            }\n            output.position(0)\n            output.limit(byteCount)\n            return FileRegion(output, packedRowStride, pixelStrideBytes)\n        } catch (t: Throwable) {\n            LargeDirectBuffer.free(output)\n            throw t\n        }\n    }\n\n    override fun close() {\n        if (closed.compareAndSet(false, true)) {\n            closeAction?.invoke()\n        }\n    }\n}\n''')

    # ImageFrame gets a lightweight disk-backing descriptor. Existing Motion constructors remain unchanged.
    p=root/REL['frame']; s=p.read_text()
    s=once(s, 'import java.nio.ByteBuffer;\n', 'import java.nio.ByteBuffer;\nimport java.io.File;\n', 'ImageFrame File import')
    s=once(s,
'''    public boolean motionV2PlaneLayoutValid = false;\n\n    public void setMotionV2PlaneLayout''',
'''    public boolean motionV2PlaneLayoutValid = false;\n\n    /* IRIS_26543_NIGHT_BOUNDED_DISK_BACKING\n     * Non-reference Night RAWs may be immutable cache files instead of long-lived malloc copies.\n     * Motion continues to use buffer exactly as before. close() owns both representations.\n     */\n    public File irisNightRawSpoolFile = null;\n    public long irisNightRawSpoolBytes = 0L;\n    public boolean irisNightRawDiskBacked = false;\n\n    public void setIrisNightRawSpool(File file, long bytes) {\n        if (file == null || bytes <= 0L) throw new IllegalArgumentException("invalid Night RAW spool");\n        irisNightRawSpoolFile = file;\n        irisNightRawSpoolBytes = bytes;\n        irisNightRawDiskBacked = true;\n    }\n\n    public boolean hasMotionV2RawBacking() {\n        return buffer != null || (irisNightRawDiskBacked && irisNightRawSpoolFile != null\n                && irisNightRawSpoolFile.isFile() && irisNightRawSpoolBytes > 0L);\n    }\n\n    public ImageFrame() {}\n\n    public void setMotionV2PlaneLayout''',
'ImageFrame disk fields')
    old='''    public void close() {\n        if (buffer != null) {\n            Allocator.free(buffer);\n            buffer = null;\n        } else {\n            Log.d("ImageFrame", "Buffer is already null, nothing to close.");\n        }\n    }\n'''
    new='''    public void close() {\n        boolean released = false;\n        if (buffer != null) {\n            Allocator.free(buffer);\n            buffer = null;\n            released = true;\n        }\n        if (irisNightRawSpoolFile != null) {\n            try {\n                if (irisNightRawSpoolFile.exists() && !irisNightRawSpoolFile.delete()) {\n                    Log.w("ImageFrame", "Could not delete Night RAW spool " + irisNightRawSpoolFile);\n                }\n            } catch (Throwable ignored) {}\n            irisNightRawSpoolFile = null;\n            irisNightRawSpoolBytes = 0L;\n            irisNightRawDiskBacked = false;\n            released = true;\n        }\n        if (!released) Log.d("ImageFrame", "No RAW backing remains to close.");\n    }\n'''
    s=once(s,old,new,'ImageFrame close')
    p.write_text(s)

    # CaptureController: bounded async disk spool for every non-reference Night frame.
    p=root/REL['capture']; s=p.read_text()
    s=once(s, 'import java.io.File;\nimport java.io.IOException;\n',
           'import java.io.File;\nimport java.io.FileOutputStream;\nimport java.io.IOException;\n', 'Capture FileOutputStream import')
    s=once(s, 'import java.util.concurrent.ExecutorService;\n',
'''import java.util.concurrent.ExecutorService;\nimport java.util.concurrent.Executors;\nimport java.util.concurrent.atomic.AtomicInteger;\n''', 'Capture executor imports')
    # Replace Night onImageAvailable branch.
    old='''            if (mIrisNight26540CaptureActive) {\n                Image nightImage = null;\n                ImageFrame copied = null;\n                try {\n                    nightImage = reader.acquireNextImage();\n                    if (nightImage == null) return;\n                    copied = copyIrisNight26540Raw(nightImage);\n                    synchronized (mIrisNight26540Lock) {\n                        if (!mIrisNight26540CaptureActive) {\n                            copied.close();\n                            copied = null;\n                        } else {\n                            mIrisNight26540Frames.add(copied);\n                        }\n                    }\n                } catch (Throwable nightRawFailure) {\n                    if (copied != null) try { copied.close(); } catch (Throwable ignored) {}\n                    Log.e(TAG, "IRIS_26540_NIGHT_RAW_COPY_FAILED", nightRawFailure);\n                    cameraEventsListener.onProcessingError("Night RAW copy: "\n                            + nightRawFailure.getClass().getSimpleName());\n                } finally {\n                    if (nightImage != null) try { nightImage.close(); } catch (Throwable ignored) {}\n                }\n                tryDispatchIrisNight26540();\n                return;\n            }\n'''
    new='''            if (mIrisNight26540CaptureActive) {\n                /* IRIS_26543_NIGHT_BOUNDED_CAPTURE_MEMORY\n                 * Keep exactly one in-memory SHORT reference. Every later Camera2 RAW is handed\n                 * directly to the bounded spool workers without creating another native copy.\n                 * At most ImageReader's three RAWs can be outstanding; capture timing remains\n                 * producer-driven unless storage itself cannot keep up with the sensor.\n                 */\n                if (!mIrisNight26543ReferenceCopied) {\n                    Image nightImage = null;\n                    ImageFrame copied = null;\n                    try {\n                        nightImage = reader.acquireNextImage();\n                        if (nightImage == null) return;\n                        copied = copyIrisNight26540Raw(nightImage);\n                        synchronized (mIrisNight26540Lock) {\n                            if (!mIrisNight26540CaptureActive) {\n                                copied.close();\n                                copied = null;\n                            } else {\n                                mIrisNight26540Frames.add(copied);\n                                mIrisNight26543ReferenceCopied = true;\n                                Log.i(TAG, "IRIS_26543_NIGHT_REFERENCE_MEMORY bytes="\n                                        + (copied.buffer == null ? 0 : copied.buffer.capacity())\n                                        + " nativeReferenceFrames=1");\n                            }\n                        }\n                    } catch (Throwable nightRawFailure) {\n                        if (copied != null) try { copied.close(); } catch (Throwable ignored) {}\n                        Log.e(TAG, "IRIS_26543_NIGHT_REFERENCE_COPY_FAILED", nightRawFailure);\n                        cameraEventsListener.onProcessingError("Night reference RAW copy: "\n                                + nightRawFailure.getClass().getSimpleName());\n                    } finally {\n                        if (nightImage != null) try { nightImage.close(); } catch (Throwable ignored) {}\n                    }\n                    tryDispatchIrisNight26540();\n                    return;\n                }\n                try {\n                    mIrisNight26543SpoolSlots.acquire();\n                } catch (InterruptedException interrupted) {\n                    Thread.currentThread().interrupt();\n                    cameraEventsListener.onProcessingError("Night RAW spool interrupted");\n                    return;\n                }\n                Image nightImage = null;\n                try {\n                    nightImage = reader.acquireNextImage();\n                    if (nightImage == null) {\n                        mIrisNight26543SpoolSlots.release();\n                        return;\n                    }\n                    final Image ownedImage = nightImage;\n                    nightImage = null;\n                    final long generation = mIrisNight26543CaptureGeneration;\n                    mIrisNight26543PendingSpools.incrementAndGet();\n                    IRIS_NIGHT_26543_SPOOL_EXECUTOR.execute(() ->\n                            spoolIrisNight26543Raw(ownedImage, generation));\n                } catch (Throwable nightRawFailure) {\n                    if (nightImage != null) try { nightImage.close(); } catch (Throwable ignored) {}\n                    mIrisNight26543SpoolSlots.release();\n                    Log.e(TAG, "IRIS_26543_NIGHT_SPOOL_SUBMIT_FAILED", nightRawFailure);\n                    cameraEventsListener.onProcessingError("Night RAW spool submit: "\n                            + nightRawFailure.getClass().getSimpleName());\n                }\n                return;\n            }\n'''
    s=once(s,old,new,'Night onImageAvailable bounded branch')

    anchor='''    private final Object mIrisNight26540Lock = new Object();\n    private final ArrayList<ImageFrame> mIrisNight26540Frames = new ArrayList<>();\n'''
    repl='''    private final Object mIrisNight26540Lock = new Object();\n    private final ArrayList<ImageFrame> mIrisNight26540Frames = new ArrayList<>();\n    /* IRIS_26543_NIGHT_BOUNDED_CAPTURE_MEMORY_OWNER\n     * ImageReader itself has maxImages=3 in fresh Night. Three spool permits therefore bound\n     * outstanding HAL RAWs exactly to the already-provisioned reader capacity; only the first\n     * SHORT gets a persistent native copy. Two workers overlap sequential UFS writes.\n     */\n    private static final int IRIS_NIGHT_26543_SPOOL_SLOTS = 3;\n    private static final long IRIS_NIGHT_26543_SPOOL_RESERVE_BYTES = 128L * 1024L * 1024L;\n    private static final long IRIS_NIGHT_26543_SPOOL_DRAIN_TIMEOUT_MS = 10_000L;\n    private static final ExecutorService IRIS_NIGHT_26543_SPOOL_EXECUTOR =\n            Executors.newFixedThreadPool(2, runnable -> {\n                Thread thread = new Thread(runnable, "IrisNightRawSpool");\n                thread.setDaemon(true);\n                return thread;\n            });\n    private final Semaphore mIrisNight26543SpoolSlots =\n            new Semaphore(IRIS_NIGHT_26543_SPOOL_SLOTS, true);\n    private final AtomicInteger mIrisNight26543PendingSpools = new AtomicInteger(0);\n    private volatile boolean mIrisNight26543ReferenceCopied = false;\n    private volatile long mIrisNight26543CaptureGeneration = 0L;\n    private volatile long mIrisNight26543SpoolDrainDeadlineMs = 0L;\n    private volatile boolean mIrisNight26543SpoolCapacityChecked = false;\n'''
    s=once(s,anchor,repl,'Night spool fields')

    # Prepare reset and stale-cache cleanup.
    old='''    private void prepareIrisNight26540CaptureState(int expectedFrames, int saveRaw,\n            boolean superRes, boolean aspect169, boolean energySaving, boolean watermark,\n            boolean binning, String cameraId, IrisMotionSettings.Snapshot irisSettings,\n            CameraCharacteristics characteristics, int rotation) {\n        if (expectedFrames < 2) throw new IllegalArgumentException("26540 Night requires >=2 frames");\n        drainIrisNight26540ReaderBeforeCapture();\n        synchronized (mIrisNight26540Lock) {\n'''
    new='''    private void prepareIrisNight26540CaptureState(int expectedFrames, int saveRaw,\n            boolean superRes, boolean aspect169, boolean energySaving, boolean watermark,\n            boolean binning, String cameraId, IrisMotionSettings.Snapshot irisSettings,\n            CameraCharacteristics characteristics, int rotation) {\n        if (expectedFrames < 2) throw new IllegalArgumentException("26540 Night requires >=2 frames");\n        drainIrisNight26540ReaderBeforeCapture();\n        if (mIrisNight26543PendingSpools.get() != 0\n                || mIrisNight26543SpoolSlots.availablePermits() != IRIS_NIGHT_26543_SPOOL_SLOTS) {\n            throw new IllegalStateException("26543 Night previous RAW spool is still active");\n        }\n        cleanupIrisNight26543SpoolCache();\n        mIrisNight26543ReferenceCopied = false;\n        mIrisNight26543CaptureGeneration++;\n        mIrisNight26543SpoolDrainDeadlineMs = 0L;\n        mIrisNight26543SpoolCapacityChecked = false;\n        synchronized (mIrisNight26540Lock) {\n'''
    s=once(s,old,new,'Night prepare reset')

    # Insert spool helpers after copyIrisNight raw.
    anchor='''    /* IRIS_26540_NIGHT_EXACT_FRAME_METADATA_OWNER */\n'''
    helpers='''    /* IRIS_26543_NIGHT_RAW_SPOOL_OWNER */\n    private File irisNight26543SpoolDirectory() {\n        File dir = new File(PhotonCamera.getApplicationContextStatic().getCacheDir(), "iris-night-raw-spool");\n        if (!dir.exists() && !dir.mkdirs())\n            throw new IllegalStateException("Cannot create Iris Night RAW spool directory");\n        return dir;\n    }\n\n    private void cleanupIrisNight26543SpoolCache() {\n        try {\n            File dir = new File(PhotonCamera.getApplicationContextStatic().getCacheDir(), "iris-night-raw-spool");\n            File[] stale = dir.listFiles((d, name) -> name.startsWith("iris26543_") && name.endsWith(".raw"));\n            if (stale != null) for (File f : stale) { try { f.delete(); } catch (Throwable ignored) {} }\n        } catch (Throwable cleanupFailure) {\n            Log.w(TAG, "IRIS_26543_NIGHT_SPOOL_STALE_CLEANUP_FAILED " + cleanupFailure);\n        }\n    }\n\n    private void spoolIrisNight26543Raw(@NonNull Image image, long generation) {\n        ImageFrame frame = null;\n        File file = null;\n        long bytes = 0L;\n        long startNs = System.nanoTime();\n        try {\n            if (image.getFormat() != ImageFormat.RAW_SENSOR)\n                throw new IllegalArgumentException("26543 Night spool requires RAW_SENSOR");\n            if (mIrisNight26540Binning)\n                throw new IllegalStateException("26543 Night disk spool requires native non-binned RAW layout");\n            Image.Plane plane = image.getPlanes()[0];\n            int rowStride = plane.getRowStride();\n            int pixelStride = plane.getPixelStride();\n            int storageWidth = rowStride / Math.max(1, pixelStride);\n            int capacity = plane.getBuffer().capacity();\n            bytes = capacity;\n            File dir = irisNight26543SpoolDirectory();\n            if (!mIrisNight26543SpoolCapacityChecked) {\n                synchronized (mIrisNight26540Lock) {\n                    if (!mIrisNight26543SpoolCapacityChecked) {\n                        long required = Math.max(0L, (long)mIrisNight26540ExpectedFrames - 1L) * capacity\n                                + IRIS_NIGHT_26543_SPOOL_RESERVE_BYTES;\n                        if (dir.getUsableSpace() < required)\n                            throw new IllegalStateException("Insufficient cache space for Night RAW spool: required="\n                                    + required + " usable=" + dir.getUsableSpace());\n                        mIrisNight26543SpoolCapacityChecked = true;\n                        Log.i(TAG, "IRIS_26543_NIGHT_SPOOL_CAPACITY expectedFrames="\n                                + mIrisNight26540ExpectedFrames + " rawBytes=" + capacity\n                                + " requiredWithReserve=" + required + " usable=" + dir.getUsableSpace());\n                    }\n                }\n            }\n            file = new File(dir, "iris26543_" + generation + "_" + image.getTimestamp() + ".raw");\n            ByteBuffer source = plane.getBuffer().duplicate();\n            source.position(0);\n            source.limit(capacity);\n            try (FileOutputStream fos = new FileOutputStream(file);\n                 java.nio.channels.FileChannel channel = fos.getChannel()) {\n                while (source.hasRemaining()) channel.write(source);\n            }\n            if (file.length() != capacity)\n                throw new IllegalStateException("Night RAW spool length=" + file.length() + " expected=" + capacity);\n            frame = new ImageFrame();\n            frame.timestamp = image.getTimestamp();\n            frame.setMotionV2PlaneLayout(image.getFormat(), image.getWidth(), image.getHeight(),\n                    rowStride, pixelStride, false);\n            frame.width = storageWidth;\n            frame.height = image.getHeight();\n            frame.setIrisNightRawSpool(file, capacity);\n            file = null; // frame.close() owns deletion from here.\n            synchronized (mIrisNight26540Lock) {\n                if (!mIrisNight26540CaptureActive || generation != mIrisNight26543CaptureGeneration) {\n                    frame.close();\n                    frame = null;\n                } else {\n                    mIrisNight26540Frames.add(frame);\n                    Log.i(TAG, "IRIS_26543_NIGHT_RAW_SPOOLED timestamp=" + frame.timestamp\n                            + " bytes=" + frame.irisNightRawSpoolBytes\n                            + " pending=" + mIrisNight26543PendingSpools.get()\n                            + " nativeCopiesPersistent=1 tookMs="\n                            + ((System.nanoTime() - startNs) / 1_000_000L));\n                    frame = null;\n                }\n            }\n        } catch (Throwable spoolFailure) {\n            if (frame != null) try { frame.close(); } catch (Throwable ignored) {}\n            if (file != null) try { file.delete(); } catch (Throwable ignored) {}\n            Log.e(TAG, "IRIS_26543_NIGHT_RAW_SPOOL_FAILED bytes=" + bytes, spoolFailure);\n        } finally {\n            try { image.close(); } catch (Throwable ignored) {}\n            mIrisNight26543PendingSpools.decrementAndGet();\n            mIrisNight26543SpoolSlots.release();\n            tryDispatchIrisNight26540();\n        }\n    }\n\n'''+anchor
    s=once(s,anchor,helpers,'Night spool helpers')

    # Drain waits for spool completion and fails cleanly rather than racing late files.
    old='''    private void finishIrisNight26540AfterDrainTimeout() {\n        boolean fail = false;\n        int matchedCount = 0;\n        int requestedCount = 0;\n'''
    new='''    private void finishIrisNight26540AfterDrainTimeout() {\n        int pendingSpools = mIrisNight26543PendingSpools.get();\n        if (pendingSpools > 0) {\n            long now = SystemClock.elapsedRealtime();\n            if (now < mIrisNight26543SpoolDrainDeadlineMs) {\n                Log.i(TAG, "IRIS_26543_NIGHT_WAITING_FOR_SPOOL pending=" + pendingSpools\n                        + " permits=" + mIrisNight26543SpoolSlots.availablePermits());\n                if (mBackgroundHandler != null)\n                    mBackgroundHandler.postDelayed(\n                            CaptureController.this::finishIrisNight26540AfterDrainTimeout, 100L);\n                return;\n            }\n            synchronized (mIrisNight26540Lock) {\n                mIrisNight26540CaptureActive = false;\n                for (ImageFrame frame : mIrisNight26540Frames)\n                    if (frame != null) try { frame.close(); } catch (Throwable ignored) {}\n                mIrisNight26540Frames.clear();\n                mIrisNight26540Results.clear();\n                mIrisNight26540Requests.clear();\n            }\n            CaptureController.isProcessing = false;\n            Log.e(TAG, "IRIS_26543_NIGHT_SPOOL_DRAIN_TIMEOUT pending=" + pendingSpools);\n            cameraEventsListener.onProcessingError("Iris Night RAW spool timeout");\n            return;\n        }\n        boolean fail = false;\n        int matchedCount = 0;\n        int requestedCount = 0;\n'''
    s=once(s,old,new,'Night drain spool wait')

