    new='''    private void tryDispatchIrisNight26540() {\n        IrisNightBatch sealedBatch = null;\n        try {\n            if (mIrisNight26543PendingSpools.get() != 0) return;\n            synchronized (mIrisNight26540Lock) {\n                if (!mIrisNight26540CaptureActive || !mIrisNight26540SequenceComplete\n                        || mIrisNight26540Dispatched || mIrisNight26540ExpectedFrames < 2) return;\n'''
    s=once(s,old,new,'Night dispatch pending gate')
    old='''                sealedBatch = new IrisNightBatch(matched, new ArrayList<>(BurstShakiness),\n'''
    new='''                int inMemoryRawFrames = 0;\n                int diskBackedRawFrames = 0;\n                for (ImageFrame frame : matched) {\n                    if (frame.buffer != null) inMemoryRawFrames++;\n                    if (frame.irisNightRawDiskBacked) diskBackedRawFrames++;\n                    if (!frame.hasMotionV2RawBacking())\n                        throw new IllegalStateException("26543 Night matched frame lost RAW backing");\n                }\n                if (inMemoryRawFrames != 1 || diskBackedRawFrames != matched.size() - 1\n                        || mIrisNight26543PendingSpools.get() != 0\n                        || mIrisNight26543SpoolSlots.availablePermits() != IRIS_NIGHT_26543_SPOOL_SLOTS) {\n                    throw new IllegalStateException("26543 Night bounded-memory proof failed memory="\n                            + inMemoryRawFrames + " disk=" + diskBackedRawFrames\n                            + " frames=" + matched.size()\n                            + " pending=" + mIrisNight26543PendingSpools.get()\n                            + " permits=" + mIrisNight26543SpoolSlots.availablePermits());\n                }\n                Log.i(TAG, "IRIS_26543_NIGHT_BOUNDED_MEMORY_PROOF frames=" + matched.size()\n                        + " inMemoryRawFrames=" + inMemoryRawFrames\n                        + " diskBackedRawFrames=" + diskBackedRawFrames\n                        + " nativePersistentCopies=1 imageReaderSlots=3 pending=0 spoolPermits=3");\n                sealedBatch = new IrisNightBatch(matched, new ArrayList<>(BurstShakiness),\n'''
    s=once(s,old,new,'Night bounded proof')

